fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // First matrix: each row is a copy of x
    let mut grid_x = Vec::with_capacity(rows);
    for _ in 0..rows {
        grid_x.push(x.clone());
    }
    
    // Second matrix: each row contains the corresponding y value repeated
    let mut grid_y = Vec::with_capacity(rows);
    for i in 0..rows {
        let mut row = Vec::with_capacity(cols);
        for _ in 0..cols {
            row.push(y[i]);
        }
        grid_y.push(row);
    }
    
    (grid_x, grid_y)
}